import type { RagDocument } from "../types";

const keeper = `## Хранительница маяка

Хранительница маяка Острель живёт в белом доме у самой воды. Каждое утро она поднимается на башню, проверяет стекло и записывает в судовой журнал силу ветра. Она не любит громких разговоров и считает, что маяк должен светить ровно, без спешки.`;

const storm = `## Штормовая запись

В ночь большого шторма смотритель маяка трижды поднимался на башню, чтобы поправить заслонку. Ветер срывал пену с волн и бросал её на стекло. Утром в журнале погоды появилась короткая запись: «Свет держался. Стекло цело. Лодку у восточного причала унесло».`;

const notes = `## Заметки о топливе

Масло для маяка привозят с южного склада два раза в месяц. Бочки ставят в подвал, подальше от печи, и подписывают мелом номер партии. Если масло пахнет дымом, его не заливают в лампу, а возвращают поставщику вместе с запиской.`;

export const ostrelLight = {
  key: "ostrel-light",
  documentName: "Острельский маяк",
  language: "ru",
  scope: "persona",
  sourceText: `# Острельский маяк

${keeper}

${storm}

${notes}`,
  passages: [
    { key: "ostrel-light.keeper", text: keeper },
    { key: "ostrel-light.storm", text: storm },
    { key: "ostrel-light.notes", text: notes },
  ],
} as const satisfies RagDocument;
